private fun readingPassageRowRowsPart0(): List<ReadingPassageRow> = listOf(
    ReadingPassageRow(
        passageId = "certyfikat-polski-B1-2017-read-1",
        examRef = "certyfikat-polski-B1-2017",
        taskNumber = 1,
        instruction = "Proszę przeczytać akapity i zaznaczyć właściwe odpowiedzi.",
        text = "1. Każdy, kto będzie chciał skorzystać z Internetu, będzie mógł to zrobić w kiosku internetowym. Na razie jest ich kilka, ale wkrótce mają się znajdować w wielu miejscach w kraju.\n\n2. Kluby aktywnego poszukiwania pracy są jedną z form pomocy dla bezrobotnych. Mają one za zadanie pobudzić ich i zmotywować do bardziej aktywnego poszukiwania pracy oraz wzbogacić o potrzebne wiadomości i umiejętności.\n\n3. W Polsce na początku lat 90. na chipsy przerabiano kilka tysięcy ton ziemniaków rocznie. Teraz – 270 tys. ton. Statystyczny Polak zjada w ciągu roku kilogram chipsów, Brytyjczyk aż pięć kilo.\n\n4. Doskonale pamiętam, jak ciężko mi było z dala od Polski. Pierwsze kilka lat w USA to była ciągła tęsknota i brak przyjaciół. Wtedy, w ciężkich chwilach ciocia powtarzała mi stale, że jak mi się tu nie podoba, to mogę wracać.\n\n5. Jeśli chcesz wziąć kredyt studencki, musisz mieć konto w banku. Stypendia i pieniądze od rodziców lepiej trzymać na koncie niż w skarpecie schowanej w akademiku.",
    ),
    ReadingPassageRow(
        passageId = "certyfikat-polski-B1-2017-read-2",
        examRef = "certyfikat-polski-B1-2017",
        taskNumber = 2,
        instruction = "Proszę przeczytać tekst, a następnie zaznaczyć: P – gdy zdanie jest prawdziwe, F – gdy jest fałszywe.",
        text = "Mentor dla cudzoziemca\n\nOla Różycka, studentka psychologii, przez cały ubiegły rok opiekowała się Martiną, Włoszką z Bolonii, która przyjechała na Uniwersytet Warszawski studiować ekonomię.\n\n– Pomagałam jej załatwiać sprawy w dziekanacie, zapisać się do biblioteki, trafić na zajęcia, znaleźć mieszkanie. Samej byłoby jej trudno, bo nie znała polskiego – wspomina Ola. Była mentorką – osobą, która pomaga zagranicznym stypendystom odnaleźć się na uczelni i w mieście. Takiego opiekuna dostaje każdy cudzoziemiec na Uniwersytecie Warszawskim. Podobnie też jest w Szkole Głównej Handlowej.\n\nTen zwyczaj przyszedł z zachodnich uczelni, na które co roku przyjeżdża wielu studentów z całego świata. Coraz więcej przybywa ich też do Polski. Polscy studenci zgłaszają się, żeby polepszyć swój angielski albo inny język. W ankiecie zgłoszeniowej podają, jaki język znają i jaka ma być płeć ich podopiecznego. Bo mentorowanie szybko zmienia się we wspólne spotkania, imprezy, przyjaźń, a czasem nawet w coś więcej…\n\nKiedy zdarza się, że opiekun nie może zająć się studentem, do akcji wkracza Grupa Szybkiego Reagowania. Zastępuje mentora, by student obcokrajowiec nie czuł się zagubiony w mieście.\n\n– Zaprzyjaźniłyśmy się z Martiną. Spędziła w moim domu Wielkanoc. Chociaż moja mama nie zna włoskiego ani angielskiego, świetnie się porozumiewała z Martiną i bardzo się polubiły – wspomina Ola. Mentorska znajomość przetrwała wakacje: piszą do siebie maile, a za pół roku będą się spotykały we Włoszech. Ola wyjeżdża na stypendium do Rzymu. I tam, jako zagraniczna stypendystka, będzie miała okazję zobaczyć, jak wygląda praca mentora od drugiej strony.",
    ),
    ReadingPassageRow(
        passageId = "certyfikat-polski-B1-2017-read-3",
        examRef = "certyfikat-polski-B1-2017",
        taskNumber = 3,
        instruction = "Proszę przeczytać tekst i dopasować usunięte z niego fragmenty.",
        text = "Spacery\n\nObecnie większość czasu spędzamy w pomieszczeniach: mieszkaniach, biurach, fabrykach. Unikamy wysiłku, nie chodzimy na piechotę, a w wolnym czasie zamiast na przykład pójść [1] oglądać telewizję. Tak jest nam wygodniej.\n\nJeśli chcesz poprawić kondycję fizyczną bez [2], wybierz łatwy i tani sposób, czyli spacer. Ruch potrzebny jest wszystkim – [3]. Największym plusem spacerów jest to, że nie musimy kupować żadnego specjalistycznego sprzętu. Trzeba mieć tylko wygodne buty. Co więcej, [4] i przy każdej pogodzie. Najlepiej spacerować w [5] i miejskiego ruchu – człowiek najlepiej wypoczywa na łonie przyrody.\n\nJuż jedna godzina spaceru dziennie [6]. Powinien to być jednak wtedy intensywny marsz, w tempie 5 – 6 kilometrów na godzinę.\n\nOdmianą spaceru jest popularny także w Polsce nordic walking, czyli dynamiczny marsz z kijkami. Ogromną zaletą tej formy ruchu jest to, że można go polecić wszystkim, a zwłaszcza [7]. Jest on bowiem bezpieczną formą aktywności, połączonej ze spędzaniem czasu na świeżym powietrzu.\n\nB. dzieciom, ludziom młodym oraz osobom starszym\nC. wydawania pieniędzy na siłownię czy aerobik\nD. miejscach zielonych i spokojnych, z daleka od dróg\nE. na spacer można się wybrać o każdej porze dnia\nF. na spacer, wolimy siedzieć w domu i\nG. osobom starszym, z różnymi problemami zdrowotnymi\nH. zwiększa naszą kondycję fizyczną",
    ),
    ReadingPassageRow(
        passageId = "certyfikat-polski-B1-2017-read-4",
        examRef = "certyfikat-polski-B1-2017",
        taskNumber = 4,
        instruction = "Proszę połączyć wypowiedzi z kolumny I z wypowiedziami z kolumny II.",
        text = "Jak zachęcić dziecko do czytania? Oto kilka wskazówek dla rodziców.\n\nA. Umówcie się z dzieckiem, że będzie mogło posiedzieć 15 minut przed telewizorem, jeśli spędzi 30 minut z książką.\nB. Dziecko, które widzi rodziców z książką, chętniej będzie szukać czegoś do czytania.\nC. Zachęcajcie dzieci, aby czytały na głos. Możecie zaplanować raz w miesiącu kolację z historią czytaną przez dziecko.\nD. Starsze dzieci zachęćcie do napisania listu lub e-maila do pisarza, którego książka je zaciekawiła.\nE. Pamiętajcie, że słuchania należy się uczyć. Nie denerwujcie się, gdy na początku dziecko nie potrafi się skoncentrować.\nF. Miejsce, gdzie stoją ulubione książki, powinno być na odpowiedniej wysokości dla dziecka.\nG. Na czytanie wykorzystujcie różne okoliczności. Może to być czas posiłków lub nawet kąpiel.\nH. Nie pytajcie, czy dziecko woli czytanie, czy oglądanie telewizji. Po prostu siadajcie obok siebie i czytajcie.",
    ),
    ReadingPassageRow(
        passageId = "certyfikat-polski-B1-2017-read-5",
        examRef = "certyfikat-polski-B1-2017",
        taskNumber = 5,
        instruction = "Proszę wybrać najlepszą z trzech możliwości podanych w nawiasach.",
        text = "W drugą rocznicę śmierci Marka Grechuty odbędzie się w Krakowie pierwsza edycja festiwalu jego twórczości pt.: „Korowód”.\n\nAnna Treter – krakowska piosenkarka i szefowa Fundacji „Piosenkarnia” opowiada:\nŻona Marka dobrze [1] koncerty piosenki literackiej przygotowywane przez Fundację i poprosiła mnie, żebym [2] koncert w drugą rocznicę śmierci jej męża. Propozycja ta zgadzała się z celami Fundacji, [3] postanowiłam zrealizować ten pomysł. Najpierw odbył się konkurs na interpretację piosenek Marka Grechuty, a [4] zdecydowaliśmy się dołączyć nowe elementy do przygotowywanego koncertu. [5] festiwalu będzie można nie tylko słuchać muzyki. Przygotowujemy również [6] obrazów Marka Grechuty. Natomiast fotograf – Adam Bujak pokaże publicznie po raz pierwszy swoje archiwalne [7], które robił Markowi Grechucie. Festiwal zakończy modlitwa w jednym z krakowskich [8], a potem wszyscy przejdą na cmentarz Rakowiecki, aby tam przy pomniku Marka Grechuty złożyć kwiaty.",
    ),
    ReadingPassageRow(
        passageId = "B1-2019-read-1",
        examRef = "certyfikat-polski-B1-2019",
        taskNumber = 1,
        instruction = "Proszę przeczytać fragmenty tekstów i zaznaczyć właściwą odpowiedź.",
        text = "1. Jeśli masz ponad 30 lat i zarejestrowałeś się jako bezrobotny, możesz otrzymać pomoc finansową na otwarcie firmy. Projekt adresowany jest też do osób, które na rynku pracy znajdują się w trudnej sytuacji – są po 50. roku życia i mają niskie kwalifikacje.\n\n2. Od października działa nowy klub fitness. Przez pierwsze dwa tygodnie zajęcia grupowe prowadzone przez profesjonalnych instruktorów są bezpłatne. Do dyspozycji klientów jest też siłownia, szatnie z prysznicami i bufet.\n\n3. Obraz Tamary Łempickiej „La Musicienne” został sprzedany w Nowym Jorku za blisko 9,1 mln dolarów (ponad 34 mln zł). Nikt nie myślał, że kwota będzie tak wysoka. Praca jest najdroższym w historii obrazem polskiego artysty.\n\n4. Już trzeci raz w rankingu gazety „Rzeczpospolita” najlepszą polską uczelnią ekonomiczną została Szkoła Główna Handlowa w Warszawie. W tegorocznym konkursie brało udział sześć uniwersytetów i 28 wydziałów.",
    ),
    ReadingPassageRow(
        passageId = "B1-2019-read-2",
        examRef = "certyfikat-polski-B1-2019",
        taskNumber = 2,
        instruction = "Proszę przeczytać tekst, a następnie zaznaczyć TAK, gdy zdanie jest zgodne z tekstem, lub NIE, gdy nie jest zgodne.",
        text = "Spóźniony samolot\n\nW jaki sposób starać się o zwrot pieniędzy za bilet, kiedy nasz samolot się spóźnił lub w ogóle nie poleciał? Jedna z linii lotniczych podała informację, że w pierwszej połowie 2016 roku aż 256 jej lotów było opóźnionych o więcej niż 3 godziny. W takiej sytuacji, zgodnie z prawem Unii Europejskiej, pasażerowie mogą dostać zwrot pieniędzy za lot.\n\n– Trudno znaleźć dokładne statystyki spóźnionych samolotów, bo takich informacji nie podają linie lotnicze. To nie jest dla nich wygodne, aby pasażerowie mogli korzystać ze swoich praw – mówi adwokat Marcin Maciejewski.\n\nWedług przepisów pasażer ma prawo do zwrotu pieniędzy, jeżeli rejs został odwołany na krócej niż 14 dni przed wylotem lub jest opóźniony o ponad 3 godziny. To, ile linie lotnicze nam zwrócą, zależy od długości lotu i może to być nawet 600 euro.\n\n– Pasażerowie często rezygnują i nie starają się o zwrot pieniędzy w przypadku spóźnionego lub anulowanego samolotu. Mówią, że to skomplikowane, nie znają prawa i muszą wypełnić dużo dokumentów – zauważa Maciejewski.\n\nDlatego też szybko rozwijają się firmy, które pomagają pasażerom w otrzymaniu zwrotu pieniędzy. – Klient przekazuje nam skany dokumentów, podpisuje umowę i czeka na przelew, a sprawą zajmuje się wyspecjalizowana firma – mówi jeden z pracowników.\n\nNa podstawie: National Geographic Traveler, „Opóźniony samolot”.",
    ),
    ReadingPassageRow(
        passageId = "B1-2019-read-3",
        examRef = "certyfikat-polski-B1-2019",
        taskNumber = 3,
        instruction = "Proszę przeczytać tekst i dopasować usunięte fragmenty A–I.",
        text = "Słynny na cały świat Jarmark Dominikański w Gdańsku ma bardzo długą tradycję, bo pierwszy raz odbył się w 1260 roku. Z historii możemy się dowiedzieć, że w XVI wieku jarmark odbywał się w sierpniu [1]. Z tej okazji na cały ten czas do Gdańska przyjeżdżali sprzedawcy z całej Europy, a razem z nimi grupy artystów ulicznych, [2]. Do miasta przypływały również wielkie statki z winem francuskim i hiszpańskim, jedwabiem, oliwą, cytrynami, konfiturami i egzotycznymi przyprawami. Przez wiele wieków było to każdego roku wielkie święto miasta [3]. Powrócono do niej w 1972 roku, ale wówczas jarmark stał się imprezą wyłącznie handlową, umożliwiającą kupowanie produktów, [4].\n\nDzisiaj jarmark jest główną atrakcją turystyczną Gdańska. Jest to największa impreza handlowo-kulturalna w Polsce, [5], kolorowa i pełna życia. Turyści z całego świata przyjeżdżają chętnie w sezonie letnim, [6]. Jedni – pyszne regionalne jedzenie: sery, wędliny, ciasta oraz kawę i różne rodzaje herbaty. Inni – spektakle i koncerty. Ludzie kupują, [7], a dla dzieci organizowane są atrakcyjne warsztaty, gry i zabawy. W czasie jarmarku nigdy nie jest nudno, [8]. Dookoła słychać radosny śmiech najmłodszych, rozmowy w wielu językach, muzykę dobiegającą ze scen. Obecnie Jarmark Dominikański rozpoczyna się zawsze w ostatnią sobotę lipca i trwa 23 dni.\n\nA. którzy bawili gości\nB. bo pierwszy raz odbył się w 1260 roku (przykład)\nC. a jednocześnie jedna z największych w Europie\nD. bo tutaj każdy znajduje coś dla siebie\nE. i dopiero druga wojna światowa przerwała tę tradycję\nF. których brakowało w tamtym czasie w sklepach\nG. bo wszędzie coś się dzieje\nH. i trwał czternaście dni\nI. słuchają muzyki, robią pamiątkowe fotografie",
    ),
    ReadingPassageRow(
        passageId = "B1-2019-read-4",
        examRef = "certyfikat-polski-B1-2019",
        taskNumber = 4,
        instruction = "Proszę połączyć tytuły z fragmentami tekstów.",
        text = "Jak polubić sprzątanie?\n\nA. Sprzątaj wtedy, kiedy masz na to ochotę. Warto wykorzystać dobry moment i po prostu zacząć sprzątać. Czy to będzie poniedziałek, czy środa, wieczór czy środek dnia, to nie ma znaczenia.\nB. To klucz do tego, by polubić porządki. Możemy powtarzać, że znów trzeba sprzątać albo chcieć to zrobić i z przyjemnością myśleć o końcowym efekcie.\nC. Jedną z najsmutniejszych rzeczy przy sprzątaniu jest brak szybkich efektów. Dlatego ogromne znaczenie ma to, czym sprzątamy. Jest w czym wybierać, wiele produktów działa rewelacyjnie w krótkim czasie.\nD. Uporządkowanie jednej półki czy szuflady brzmi mniej strasznie niż posprzątanie całego mieszkania. To idealne rozwiązanie, gdy trudno nam się zmobilizować do sprzątania.\nE. Szkoda ci czasu na porządki? Podczas sprzątania możesz słuchać muzyki, audycji radiowych, a prasowanie można połączyć z oglądaniem ulubionego programu.\nF. Lubisz książki – wyczyść je i poukładaj np. kolorami, lubisz modę i ubrania, zrób porządek w szafie, kolekcjonujesz płyty – zrób ich listę, kochasz gotować – zacznij od sprzątania w kuchni czy posegregowania przepisów.\nG. To, dlaczego sprzątamy, jest najważniejsze. Czasami, bo przychodzą goście. Przede wszystkim jednak dlatego, że lubimy żyć w porządku, wtedy czujemy się lepiej i jesteśmy szczęśliwsi.",
    ),
    ReadingPassageRow(
        passageId = "B1-2019-read-5",
        examRef = "certyfikat-polski-B1-2019",
