        instruction = "Proszę uzupełnić tekst wyrazami z ramki.",
        text = "Akcja „Majewskich posadzili” jest częścią kampanii, którą prowadzi fundacja „Zmiana”. W polskich więzieniach nie ma [1], wydanych w ostatnim czasie książek. Powód jest prosty – ich ceny są za [2]. Dlatego grupa fanów literatury postanowiła [3] zbiórkę. Celem akcji było zachęcenie wszystkich [4] Warszawy do oddawania swoich książek do zakładów karnych. Organizatorzy tak tłumaczyli nazwę kampanii: Majewski to [5] nazwisko, każdy z nas zna jakiegoś Majewskiego. Każdy z nas słyszał też o kimś, kto znalazł się w więzieniu. Chcemy zwrócić uwagę na fakt, że w tego typu miejscach są osoby, które po wyjściu na [6] mają możliwość rozpoczęcia nowego życia. Dzięki mądrym książkom dajemy szansę nie tylko [7], ale też starszym, którzy chcą się zmienić. Mogą oni zwrócić [8] lub zatrzymać ją na zawsze. Do akcji [9] kilka znanych osób, między innymi piosenkarka Alicja Majewska i showman Szymon Majewski – noszą oni nazwisko, które [10] w kampanii.\n\nWyrazy z ramki: pojawiło się; częścią (przykład); wysokie; nowych; zorganizować; mieszkańców; książkę; młodzieży; wolność; przyłączyło się; popularne.",
