        title = "Przechodzenie na ty",
        instruction = "Proszę przeczytać tekst i dopasować usunięte fragmenty A–K. C jest przykładem; jeden fragment jest zbędny.",
        text = "W kraju nad Wisłą nauczeni jesteśmy zwracać się do siebie na pan/pani, chociaż oczywiście są miejsca, w których te [C], czego najlepszy przykład stanowią media społecznościowe, gdzie nie stosuje się zwrotów formalnych i to [1]. Na dobre rytuał przechodzenia na ty zagościł w korporacjach. To wynik [2], zwłaszcza amerykańskich. Szefowie dużych firm wierzą, że efektywność pracy całego zespołu poprawi się, jeśli zapanuje większa swoboda w relacjach między pracownikami, a przejście na ty [3].\n\nTrudno oceniać, czy to dobrze, czy źle, że użytkownik języka polskiego [4], stosując formy pan/pani. Dla jednych to filar dobrego wychowania i wyraz szacunku dla rodzimej tradycji, dla drugich przejaw dziwnej mentalności, wywyższania się, a zarazem przeszkoda w promowaniu [5].\n\nObecnie między Polakami z różnych powodów wyrasta coraz większy mur. Jak wynika z badań, ponad 65 proc. Polaków [6] i nie ma z nimi bliskich kontaktów, a badania innego ośrodka informują, że co drugi Polak nie zna nawet ich imienia. Jednak bez względu na punkt widzenia, każdemu wcześniej czy później zdarza się przejść z kimś na ty. Mamy przecież więcej niż kiedyś okazji, żeby [7]. Wystarczy tylko się odważyć.\n\nRaczej nie ma sensu oglądać się na innych, oczekując, że [8], tak jak miało to miejsce w Szwecji, gdzie pod koniec lat 60. XX wieku przeprowadzono reformę i zaczęto mówić sobie na ty niezależnie od wieku, wykształcenia i statusu. Taka ogólnokrajowa reforma w polskiej rzeczywistości to na razie fikcja. Lepiej więc szukać metod oddolnych. Na przykład okazji do [9], które nie będą wymagały mówienia do drugiej osoby na pan/pani.\n\nRzecz przecież nie w tym, by mówić sobie na ty dla samej sztuki mówienia; chodzi raczej o to, żeby taka forma komunikacji była czymś naturalnym, wyrażała czystą sympatię i pomagała [10].\n\nA. wykorzystywania wzorców zachodnich\nB. utrzymuje dystans w relacjach z sąsiadami\nC. grzecznościowe więzy możemy poluzować (przykład)\nD. wciąż sięga po zwroty grzecznościowe\nE. równości w codziennych kontaktach towarzyskich\nF. nawiązywania znajomości\nG. zwracać się do sobie po imieniu\nH. niezależnie od wieku czy płci internautów\nI. znacznie skraca ten dystans\nJ. pielęgnować dobre relacje z ludźmi\nK. zmiana przyjdzie z góry",
    ),
    ReadingPassageRow(
        passageId = "certyfikat-polski-B2-2019-read-3",
        examRef = "certyfikat-polski-B2-2019",
        taskNumber = 3,
        title = "Rozmowa z Krzysztofem Zalewskim",
        instruction = "Połącz pytania 1–10 z fragmentami odpowiedzi A–K. F jest przykładem; jeden fragment jest zbędny.",
        text = "Rozmowa z Krzysztofem Zalewskim, autorem piosenki do filmu „Kurier” o Janie Nowaku-Jeziorańskim.\n\n1. Co wpłynęło na Twoją decyzję o udziale w tym projekcie?\n2. Jak wyglądała praca nad piosenką do „Kuriera”?\n3. Czy łatwo było napisać tekst?\n4. Co Cię najbardziej zafascynowało w historii Nowaka-Jeziorańskiego?\n5. Nie jest to Twoja pierwsza przygoda z kinem historycznym. To przypadek?\n6. Jak Twoim zdaniem powinien wyglądać współczesny patriotyzm?\n7. Niektórzy mówią, że artyści są od grania, a nie manifestowania poglądów politycznych. Jakie jest Twoje zdanie?\n8. Karierę zaczynałeś od ciężkich brzmień, teraz zmieniłeś styl. Nie brakuje Ci metalu?\n9. Sięgnąłeś też po twórczość Czesława Niemena, nie obawiałeś się reakcji publiczności?\n10. Jakie są Twoje muzyczne plany?\n\nA. Najpierw obejrzałem film w wersji bez udźwiękowienia i efektów specjalnych. W międzyczasie przypomniałem sobie też książkę Nowaka-Jeziorańskiego „Kurier z Warszawy”.\nB. Trzeba chodzić na wybory, uczestniczyć w lokalnych inicjatywach, segregować śmieci, sprzątać po psie, a przede wszystkim uśmiechać się do swojego sąsiada.\nC. Każdy obywatel ma prawo wygłaszać własne opinie. Moim przywilejem jest to, że mam forum, na którym te poglądy mogę wykrzyczeć.\nD. Dostałem szansę, by stworzyć coś swojego, a przy okazji dołożyć cegiełkę do ważnego i potrzebnego filmu.\nE. Początkowo strasznie się nad nim męczyłem. Na szczęście z pomocą przyszedł Michał Wiraszko, z którym kiedyś grałem w zespole Muchy.\nF. Nie, to raczej przypadek. Zwykle komponuję i piszę sam, czasem pojawiają się propozycje na utwór do konkretnego wydarzenia i tak było w tym przypadku. (przykład)\nG. Staram się nie ograniczać, nie narzucać sobie żadnych ram. W muzyce jest tyle pięknych dźwięków i stylów, że żal z nich nie skorzystać.\nH. Już po wydaniu płyty zastanawiałem się, dlaczego ludzie ją polubili. Może wyczuli, że robię to szczerze, z otwartym sercem i miłością do muzyki?\nI. Dla mnie tak, ale może producenci „Kuriera” wywnioskowali, że interesuję się II wojną światową.\nJ. Fajnie byłoby jeszcze pośpiewać wspólnie z Dawidem Podsiadłą. Teraz skupiam się na trasie koncertowej i zbliżającym się występie.\nK. Fakt, że to wszystko wydarzyło się naprawdę. Myślę, że z jego życiorysu można by zrobić wiele filmów.",
    ),
    ReadingPassageRow(
        passageId = "certyfikat-polski-B2-2019-read-4",
        examRef = "certyfikat-polski-B2-2019",
        taskNumber = 4,
        title = "Zmiany klimatu w Arktyce",
        instruction = "Proszę przeczytać tekst i zaznaczyć TAK, NIE lub BI (brak informacji).",
        text = "Zmiany klimatu dokonują się w Arktyce dwukrotnie szybciej niż gdziekolwiek na świecie. Choć w globalne ocieplenie trudno uwierzyć, będąc na mroźnej i zasypanej śniegiem północy, to o tym, że klimat się zmienia, wiedzą doskonale tutejsze zwierzęta, zwłaszcza ryby, które są ekstremalnie wrażliwe na wahania temperatury i pH wody. Jeśli coś przestaje im odpowiadać, przenoszą się coraz dalej i dalej na północ. Te ryby, które zostają, przede wszystkim łososie, potrzebujące słodkowodnych rzek, rosną mniejsze niż kiedyś. Tak dzieje się już od kilku lat. Cieplej robi się również na lądzie. Rozmarza ziemia, a nieliczne w tym rejonie lasy wymierają masowo przez niespotykaną dotąd liczbę insektów. Upodobały sobie one brzozy, jedne z niewielu gatunków drzew, które dobrze rosną w arktycznym klimacie.\n\nZmienia się także życie ludzi, którzy od tysięcy lat zasiedlali te rejony. W niczym nie przypomina już życia ich dziadków czy pradziadków, których określano mianem Eskimosów (a które to określenie ludy Arktyki uznają dziś często za obraźliwe i wzmacniające negatywne stereotypy). Nie ma już ubranych w skóry ludzi prowadzących koczowniczy tryb życia, budujących igloo, przenoszących się z miejsca na miejsce za stadami fok. Teraz mają „normalne” domy i pracę. Ludom tym nie zawsze jest jednak po drodze z organizacjami ekologicznymi, które pod sztandarem walki o przyrodę Arktyki coraz częściej popadają w konflikty z lokalnymi społecznościami. Ludzie na dalekiej północy wciąż polują, czasami jeden myśliwy dostarcza żywność aż siedmiu rodzinom. Polowanie na foki i białe niedźwiedzie jest częścią ich kultury, a teraz prowadzą o to ciągłe wojny z ekologami, którzy przedstawiają ich światu jako morderców ginących gatunków. Tymczasem fok są miliony, a białe niedźwiedzie mają się świetnie, co potwierdziło ostatnie liczenie tych zwierząt przez naukowców. Obserwuje się jednak, że i one przemieszczają się w inne niż zazwyczaj rejony – w ślad za rybami.",
    ),
    ReadingPassageRow(
        passageId = "certyfikat-polski-B2-2019-read-5",
        examRef = "certyfikat-polski-B2-2019",
        taskNumber = 5,
        title = "Kawa: smak i aromat",
        instruction = "Proszę uzupełnić tekst słowami z ramki. Trzy wyrazy są zbędne.",
        text = "Ramka: chronią, postanawiają, zależnością, nadają, niepożądanych, oczyszczają, cennych, warunki, smaku, pomieszczenie, uzależnieniem, używkę, zapach, zastanawiają się.\n\nPrzez lata kawa uchodziła za używkę (przykład), napój bez żadnych wartości odżywczych. Miała jedynie pobudzać, ale jej zbyt częste picie groziło [1]. Przed kilku laty opinia o tym napoju uległa zmianie. Okazało się bowiem, że kawa jest bogata w składniki, które [2] organizm przed wieloma chorobami.\n\nJak jednak przyrządzić kawę, by nie smakowała jak lekarstwo? Nad tym [3] ostatnio fizycy i chemicy. Już ustalili, że na smak i aromat kawy wpływają zarówno [4] palenia ziaren, jak też sposób ich mielenia i parzenia.\n\nŚwieżo zebrane ziarna kawy są zielone, pachną trawą, sianem, świeżymi roślinami. Napój, jaki z nich powstaje, jest nijaki w [5]. Wszystko dlatego, że zielone ziarna kawy mają zaledwie 25 substancji aromatycznych i smakowych. Dopiero dzięki procesowi palenia powstaje ok. 1000 takich substancji. W temperaturze 200-250⁰C w ziarnach zachodzą reakcje, które [6] kawie charakterystyczny smak oraz niepowtarzalny zapach. Od czasu trwania tych procesów zależy, które smaki i aromaty będą dominować. Krótki czas palenia sprawia, że kawa ma owocowy, kwaskowy [7], a długi – nadaje jej specyficzny, bardziej „spieczony” aromat.\n\nWiadomo, że woda do parzenia kawy powinna mieć ok. 92⁰C. Za niska temperatura wydobędzie zbyt mało [8] składników. Napój będzie miał nieco cierpki smak, przypominający niedojrzałe owoce. Natomiast zbyt gorąca woda sprawi, że kawa będzie przepalona. Z cząsteczek uda się co prawda wydobyć większość związków aromatycznych, ale obok tych smacznych pojawi się wiele [9].\n\nKawa może też źle smakować, gdy [10], w którym się ją podaje, jest słabo oświetlone lub napój jest pity w nieodpowiednich filiżankach i o niewłaściwej porze. Najlepiej smakuje kawa wypijana ok. godziny 11. Wtedy nasze narządy zmysłu pracują najsprawniej i są w stanie wyczuć nawet najbardziej subtelne nuty zapachów i smaków.",
    ),
    ReadingPassageRow(
        passageId = "certyfikat-polski-B2-2020-read-1",
        examRef = "certyfikat-polski-B2-2020",
        taskNumber = 1,
        title = "Pięć krótkich tekstów",
        instruction = "Proszę przeczytać fragmenty tekstów i zaznaczyć właściwą odpowiedź.",
        text = "1. Nawet kilkanaście procent Polaków jest uczulonych na zwierzęta, część z nich na kota. To specyficzna i trochę zapomniana alergia, która nieleczona może doprowadzić do astmy. Często utrudnia życie alergikowi nawet wtedy, gdy zwierzęcia nie ma w pobliżu i wydawałoby się, że nie ma też alergenu.\n\n2. Nasze społeczeństwo się bogaci – chętnie sięgamy po kolejne sprzęty coraz nowszych generacji. Urządzenia gospodarstwa domowego nie są największym problemem. Postęp techniczny w dziedzinie smartfonów czy komputerów jest bardziej dynamiczny i to właśnie je najchętniej zastępujemy nowymi, a stare urządzenia nie zawsze trafiają do właściwej utylizacji.\n\n3. Choć 90 procent z nas ma wiejskie korzenie, to o nich zapominamy albo celowo wypieramy ze świadomości. Przymiotnik „wiejski” kojarzy się nam negatywnie, tymczasem np. we Francji, kiedy mówisz, że jesteś ze wsi, od razu pytają cię, jakie sery i wino są tam produkowane.\n\n4. Znam osoby, które kilka razy okrążyły planetę w powietrzu, ale co widziały? Niewiele. Mnie interesuje autentyczny koloryt lokalny, a nie tylko wielkie miasta, w których działają lotniska międzynarodowe. Współczesne metropolie są do siebie podobne, a ludzi prawdziwych, ciekawych i otwartych można spotkać wyłącznie na prowincji.\n\n5. Słońce, na którym suszymy pranie, wcale nie jest tak niewinne, jak się wydaje. Natomiast suszarka tradycyjna na każdym ubraniu zostawia ślad w postaci mało estetycznej linii. W suszarkach automatycznych materiały nie tylko zachowują kolory, ale są traktowane bardzo delikatnie. Proces suszenia można dostosować zarówno do rodzaju tkaniny, jak i do stopnia wilgotności.",
    ),
    ReadingPassageRow(
        passageId = "certyfikat-polski-B2-2020-read-2",
        examRef = "certyfikat-polski-B2-2020",
        taskNumber = 2,
        title = "Czy wiesz, czym oddychasz w biurze?",
        instruction = "Proszę przeczytać tekst i dopasować usunięte fragmenty A–K. C jest przykładem; jeden fragment jest zbędny.",
        text = "Myśląc o zanieczyszczeniach, najczęściej skupiamy się na smogu, [C]. Tymczasem niebezpieczne może być także powietrze, którym oddychamy w biurze. I nie jest to wcale wina smogu, który może [1].\n\nNowe badania sugerują, że [2], którzy nieświadomie przenoszą i rozpraszają niezdrowe lotne związki, [3]. Narażenie na działanie takich substancji może być bardzo szkodliwe, [4]. Ponieważ większość z nas spędza minimum 40 godzin tygodniowo w biurze, warto [5], może wpływać na nasze zdrowie.\n\nBadacze nie mają dobrych wiadomości. Chemia powietrza w pomieszczeniu jest dynamiczna. Zmienia się w ciągu dnia, [6], sposobu działania systemu wentylacyjnego i liczby pracowników w biurze. Badania wykazały, że wskaźniki obecności w powietrzu wielu związków [7]. Jeśli przestrzeń biurowa nie jest odpowiednio wentylowana, te lotne związki niekorzystnie [8].\n\nJednym ze związków obniżających jakość powietrza jest izopren, łatwopalna substancja obecna w olejkach eterycznych. Naukowcom udało się nawet [9]. Co ciekawe, lotne chemikalia obecne w dezodorancie, produktach do makijażu i produktach do pielęgnacji włosów mogą [10]. Dzieje się tak, ponieważ systemy wentylacyjne wyciągają powietrze i wyrzucają je na zewnątrz.\n\nA. zastanowić się, jak powietrze, którym oddychamy w miejscu pracy\nB. bywają w pomieszczeniach 10-20 razy wyższe niż poza nimi\nC. winą obarczając przemysł, samochody i stare piece (przykład)\nD. używając dezodorantów, lakierów do włosów, a nawet – oddychając\nE. dostawać się do budynku, ale w znacznej mierze – nas samych\nF. pozostając w ścisłej zależności od warunków zewnętrznych\nG. wpływają na zdrowie i wydajność pracowników\nH. w równym stopniu wpływać na jakość powietrza w biurze, jak i poza nim\nI. przyczyną największego zanieczyszczenia powietrza biurowego są ludzie\nJ. wykryć tę substancję w oddechu osób pracujących w biurze\nK. przyczyniając się do rozwoju raka, chorób płuc, a nawet chorób serca",
    ),
    ReadingPassageRow(
        passageId = "certyfikat-polski-B2-2020-read-3",
        examRef = "certyfikat-polski-B2-2020",
        taskNumber = 3,
        title = "Rozmowa – tytuły i fragmenty",
        instruction = "Proszę połączyć tytuły 1–10 z fragmentami A–K. F jest przykładem dla „Pozory komunikacji”; jeden fragment jest zbędny.",
        text = "1. To, co niewypowiedziane\n2. Informacja to nie wszystko\n3. Klucz do sukcesu zawodowego\n4. Zasada wzajemności\n5. Tylko dla twoich uszu\n6. Bez osądzania\n7. Po prostu bądź!\n8. Nie każda rada jest dobra\n9. Mimo wszystko – rozmawiamy!\n10. Za późno na rozmowę\n\nA. Coraz więcej psychoterapeutów i filozofów postrzega komunikację nie tylko jako przekazywanie sobie informacji, ale dialog, współdziałanie, proces.\nB. Często w traumatycznej sytuacji za wszelką cenę chcemy uspokoić rozmówcę albo odwrócić jego uwagę od problemu, a wystarczy zwyczajnie potrzymać za rękę.\nC. Udzielanie wskazówek, o które nikt nie prosi, jest wtrącaniem się i komunikatem typu: „Jesteś głupi, więc ci powiem, jak trzeba to zrobić”.\nD. Zamiast oceniać trzeba skoncentrować się na opisie sytuacji, którą rozmówca przedstawia, i na problemie.\nE. Przyjęło się, że komunikacja między ludźmi to przede wszystkim komunikacja werbalna, jednak ok. 60 proc. informacji czerpiemy z mowy ciała czy mimiki.\nF. Choć wydaje się, że nie ma nic prostszego niż rozmowa, często nasz rozmówca lub my sami wyczuwamy w trakcie dialogu zagrożenie lub przewidujemy, że ono się pojawi. (przykład)\nG. Zdolność słuchania to połowa sukcesu w komunikacji interpersonalnej, drugą jest dzielenie się z innymi ważnymi dla siebie przeżyciami.\nH. Aby druga osoba chciała nam swobodnie opowiedzieć o sobie, przede wszystkim trzeba być dyskretnym.\nI. Trzeba też zdać sobie jasno sprawę, że niektórych rozmów już nie da się przeprowadzić. Pewnych ważnych rzeczy nie da się powiedzieć, bo np. bliska osoba umarła.\nJ. Umiejętność słuchania jest rzadka, a jej rozwinięcie stanowi gwarancję sukcesu w wielu zawodach: od psychoterapeuty czy lekarza po fryzjera.\nK. Biorąc pod uwagę to, jak ludzie się od siebie różnią i z jakim wysiłkiem akceptują tę inność, cudem jest, że czasem dochodzi do autentycznej komunikacji.",
    ),
    ReadingPassageRow(
        passageId = "certyfikat-polski-B2-2020-read-4",
        examRef = "certyfikat-polski-B2-2020",
        taskNumber = 4,
        title = "Podróże po Jurze",
        instruction = "Proszę przeczytać tekst i zaznaczyć TAK, NIE lub BI (brak informacji).",
        text = "Poznawanie zamków, zabytków, jaskiń oraz innych ciekawych przyrodniczo lub krajobrazowo miejsc Jury Krakowsko-Częstochowskiej ma ułatwiać gra planszowa „Podróże po Jurze”. O wydaniu gry poinformował częstochowski urząd miasta. Wydawnictwu patronują Śląska i Małopolska Organizacja Turystyczna oraz Związek Gmin Jurajskich.\n\nCelem gry – oprócz dobrej zabawy, nauki logicznego myślenia i planowania – jest zapoznanie graczy z geografią oraz atrakcjami Jury Krakowsko-Częstochowskiej. Odwiedzając zamki, zabytki, jaskinie oraz inne charakterystyczne miejsca Jury, zdobywa się punkty.\n\nGra zawiera planszę z mapą, na której odwzorowano sieć dróg Jury, pionki-samochodziki, pionki symbolizujące remont drogi, 110 kart z atrakcjami turystycznymi oraz inne elementy służące rozgrywce. W zabawie może wziąć udział od dwóch do sześciu osób – indywidualnie albo też w dwóch lub trzech drużynach.\n\nNakład gry to na razie tysiąc egzemplarzy. Oprócz możliwości zamówienia jej na stronie producenta, ma być ona niebawem dostępna w sprzedaży, np. przy punktach informacji turystycznej na terenie Jury.\n\nChoć to pierwsza tego typu gra, to jest już kolejnym pomysłem promującym Jurę Krakowsko-Częstochowską i tamtejsze produkty turystyczne. Na 22 września br. samorządy woj. śląskiego i małopolskiego przygotowują pierwszą edycję święta Szlaku Orlich Gniazd, które odbędzie się w kilkunastu obiektach i gminach położonych między Krakowem i Częstochową.\n\nWykreowanie Szlaku Orlich Gniazd i święta z nim związanego oraz organizacja festiwalu kultury lokalnej to wspólna strategia rozwoju woj. śląskiego i małopolskiego, przyjęta w obu regionach pięć lat temu.\n\nZ kolei w ostatnich dniach częstochowski samorząd uruchomił internetowy przewodnik dla rowerzystów bramajury.pl. Strona zawiera na razie 30 tras z opisem, przekrojem i śladem GPS (wkrótce mają być też udostępnione w postaci aplikacji mobilnej). Projekt jest rozwojowy: można do niego zgłaszać kolejne, autorskie propozycje tras.",
    ),
    ReadingPassageRow(
        passageId = "certyfikat-polski-B2-2020-read-5",
        examRef = "certyfikat-polski-B2-2020",
        taskNumber = 5,
        title = "Uniwernast",
        instruction = "Proszę uzupełnić tekst, wybierając najlepszą spośród podanych możliwości.",
        text = "Na ten uniwersytet (wyślesz, prześlesz, przepiszesz, nadasz) [PRZYKŁAD] dzieci jeszcze przed osiemnastką.\n\n„Uniwernast” to program, w ramach którego nastolatki mogą sprawdzić, jak to jest rozwijać swoją wiedzę z [1] nauk ścisłych i przyrodniczych poza szkołą. Idealna alternatywa dla tych, którzy [2] wyprowadzą wzór czy wyuczą się regułki, ale jednocześnie bardzo się przy tym wynudzą. [3] dla nich, w ramach projektu, zadania będą zdecydowanie bardziej kreatywne. Organizator stawia sobie ambitny cel: [4] nastolatków ze specyfiką pracy naukowca.\n\nNa pytanie, czy w realiach polskiej szkoły jest miejsce, aby poznawać, a nie wkuwać, chyba każdy z nas potrafi odpowiedzieć. Dla uczestników programu [5] podstaw analizy danych jest pierwszym zadaniem, z jakim będą musieli sobie poradzić. To jednak dopiero rozgrzewka. Zarejestrowani uczniowie [6] status stażystów tego niestandardowego uniwersytetu i będą otrzymywać różne zadania do wykonania. Tematyka tych łamigłówek będzie [7] chociażby biologię, informatykę czy astrofizykę. Gra rekrutacyjna programu jest wyzwaniem zarówno dla uczestników, jak i dla organizatorów, którzy dbają o jej atrakcyjność i wysoki [8] merytoryczny. Potwierdzają oni, że sukcesu nie [9] tu znajomość spisu treści kilku podręczników, a raczej kreatywne podejście do przedstawionych zagadnień oraz umiejętność łączenia ze sobą [10] nieoczywistych faktów.",
    ),
)

