oo, zapewniają, że warto. Nie może więc dziwić, że wrocławskie zoo\nz każdym miesiącem staje się coraz ......................................................................10\n(atrakcyjne)10 miejscem turystycznym w regionie.\nNa podstawie: http://wroclaw.wyborcza.pl/wroclaw/1,35771,20387920,afrykarium-i-zoo-z-wieksza-frekwencja-niz-wawel-i-\nwieliczka.html?disableRedirects=true",
